import React from 'react';
import './App.css';
// CORRECTED PATH! Add "components/" before DailyTracker
import DailyTracker from './components/DailyTracker'; 

// Import Poppins Fonts 
import "@fontsource/poppins/300.css";
import "@fontsource/poppins/400.css";
import "@fontsource/poppins/500.css";
import "@fontsource/poppins/600.css";
import "@fontsource/poppins/700.css";

function App() {
  return (
    <div className="dashboard-bg">
      <div className="dashboard-wrapper">
        
        {/* --- BEAUTIFUL GLASS SIDEBAR --- */}
        <div className="sidebar">
          <div>
            <h4 className="fw-bold mb-4" style={{color: '#6366F1', fontSize: '24px'}}>
              🚀 RoadMap
            </h4>
            
            <div className="sidebar-nav">
              <a href="#">🏠 Dashboard</a>
              <a href="#" className="active">📅 Daily Tracker</a>
              <a href="#">🗺️ Roadmap</a>
              <a href="#">📊 Progress</a>
            </div>
          </div>

          <div>
            <div className="mb-3 pt-3 border-top">
              <p className="mb-0 fw-bold" style={{fontSize: '14px'}}>User</p>
              <p className="text-secondary" style={{fontSize: '12px'}}>user@email.com</p>
            </div>
            <button className="logout-btn">🚪 Logout</button>
          </div>
        </div>

        {/* --- MAIN CONTENT AREA --- */}
        <div className="flex-grow-1">
            
          {/* --- HERO BANNER (The beautiful purple gradient) --- */}
          <div className="hero-gradient">
            <h1 className="hero-title">Welcome Back! 👋</h1>
            <p className="hero-subtitle">Build. Learn. Improve every day.</p>
            <div className="d-flex gap-4 mt-3">
                <div><span className="stat-number">5</span> <span className="stat-label">Day Streak</span></div>
                <div><span className="stat-number">35%</span> <span className="stat-label">Progress</span></div>
                <div><span className="stat-number">120</span> <span className="stat-label">Days Left</span></div>
            </div>
          </div>

          {/* --- YOUR DAILY TRACKER COMPONENT LIVE HERE --- */}
          <div className="premium-card p-4">
             {/* This renders all your hooks and API calls! */}
            <DailyTracker /> 
          </div>

        </div>
      </div>
    </div>
  );
}

export default App;
